interface SecretProvider { String fetchSecret(String key); } // reprezentuje Vault/AWS Secrets Manager

class CachingSecretStore {
    private final SecretProvider provider;
    private final Duration ttl;
    private final Map<String, Map.Entry<String, Instant>> cache = new ConcurrentHashMap<>();

    CachingSecretStore(SecretProvider provider, Duration ttl) {
        this.provider = provider; this.ttl = ttl;
    }

    String getSecret(String key) {
        var cached = cache.get(key);
        if (cached != null && Instant.now().isBefore(cached.getValue())) {
            return cached.getKey(); // w oknie TTL - BEZ dodatkowego zapytania do vaulta
        }
        String fresh = provider.fetchSecret(key); // TTL wygasl - swiezy odczyt
        cache.put(key, Map.entry(fresh, Instant.now().plus(ttl)));
        return fresh;
    }
}

